def _validate_changes(request: dict, records_by_id: dict[str, dict]) -> list[dict]:
    """Validate a correct request against the state it is applied to.

    Every target must currently exist, belong to the request subject and
    resolve to an existing object member or array element; no two paths
    touching the same record may be equal or ancestor/descendant of each
    other. Returns the validated changes ordered by record_id then path.
    """
    changes = request["changes"]
    assert changes is not None
    per_record: dict[str, list[dict]] = {}
    for change in changes:
        record = records_by_id.get(change["record_id"])
        if record is None:
            raise InvalidCorrection("change target record must exist at request time")
        if record["subject_id"] != request["subject_id"]:
            raise InvalidCorrection("change target record must belong to the request subject")
        if _resolve(record["data"], change["segments"]) is _MISSING:
            raise InvalidCorrection(
                "change path must point to an existing member or array element"
            )
        per_record.setdefault(change["record_id"], []).append(change)
    for record_changes in per_record.values():
        ordered = sorted(record_changes, key=lambda change: change["segments"])
        for i, change in enumerate(ordered):
            for other in ordered[i + 1 :]:
                if change["segments"] == other["segments"] or _is_ancestor(
                    change["segments"], other["segments"]
                ):
                    raise InvalidCorrection("change paths must not repeat or be ancestors of each other")
    ordered_changes = sorted(changes, key=lambda change: (change["record_id"], change["path"]))
    return [{"record_id": change["record_id"], "path": change["path"]} for change in ordered_changes]

