def test_pointer_escapes_resolve(self):
    records = [record("r1", "s1", {"a/b": {"~x": 1}})]
    out = process_subject_requests(
        {
            "records": records,
            "requests": [
                correct_req("q", "s1", [change("r1", "/a~1b/~0x", 42)])
            ],
        }
    )
    self.assertEqual(out["records"][0]["data"], {"a/b": {"~x": 42}})

